    assert monitor_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_pooled_flag_rate_weights_transcripts_and_ignores_empty_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_log_none_fields_and_skip_lines():
    assert parse_transcript_log(["  # ignored", "  ", " x1 , 3 , "]) == [
        {"id": "x1", "day": 3, "flagged": None}
    ]


def test_parse_log_errors_include_original_line_number():
    try:
        parse_transcript_log(["# comment", "bad,line"])
    except ValueError as exc:
        assert "line 2" in str(exc)
    else:
        assert False, "expected ValueError"


def test_dedupe_keeps_last_record_for_duplicate_id():
    old = {"id": "a", "day": 1, "flagged": True}
    new = {"id": "a", "day": 3, "flagged": False}
    other = {"id": "b", "day": 2, "flagged": True}
    assert dedupe_transcripts([old, other, new]) == [other, new]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 2, "flagged": True},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_uses_three_decimals_and_nonempty_group_count():
    groups = {
        "a": [{"id": "a", "day": 1, "flagged": True}],
        "b": [{"id": "b", "day": 2, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.5, "recent": 1, "groups": 2}


def test_top_flagged_groups_ties_are_alphabetical_and_empty_groups_excluded():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": True}],
        "empty": [],
        "a": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["b", "z"]


def test_group_rates_are_sorted_and_empty_groups_have_none_rate():
    groups = {"z": [], "b": [{"flagged": True}], "a": [{"flagged": False}]}
    assert list(flag_rate_by_group(groups)) == ["a", "b", "z"]
    assert flag_rate_by_group(groups)["z"] is None


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, 3]) == 2
    assert longest_flag_streak([-1, 0]) == 0
